// Base64-encoded EB Garamond TTF files (Regular/Bold/Italic/BoldItalic), subset to
// Latin + common punctuation to keep this small (~40KB each). Instanced from the
// variable-font source (github.com/google/fonts, ofl/ebgaramond) at wght=400/700
// using fonttools, since jsPDF needs a static (non-variable) TTF. Only imported
// inside the PDF export path (dynamic import) so it never bloats the main bundle.
// Matches the editor's on-screen serif font exactly (styles/globals.css .serif-t).

export const ebGaramondRegular = "";

export const ebGaramondBold = "";

export const ebGaramondItalic = "";

export const ebGaramondBoldItalic = "";
